-- =============================================================================
-- 20261025100000 — Tag Bible names and places (issue #75)
--
-- About 2,660 of the 15,610 words are personal and place names from the Motu
-- Bible (iehova, iesu, ierusalem, aigupto...), not Motu vocabulary. They're
-- tagged, not deleted: Motu-ised names are worth keeping in the dictionary.
--
-- 1. words.word_type ('vocabulary' | 'name', default 'vocabulary').
-- 2. 'name' is set from a fixed, reviewed list generated by
--    scripts/classify-names.mjs from data/bible-indices/verses.json: words
--    never written in lower case and capitalised mid-sentence at least once,
--    plus israel and mose (names with lower-case typos, checked by hand).
--    The list (with evidence) is data/word-types/names.tsv. Words an admin
--    has already re-tagged (moderation_log 'set_word_type') are left alone,
--    so re-running this never undoes a correction.
-- 3. get_next_word_for_user never offers a name (signature unchanged).
-- 4. word_initials and search_words take an optional p_word_type; with it
--    left out they behave as before (every word), so the app deployed before
--    this migration keeps working. word_neighbors walks within the current
--    word's type.
-- 5. moderation_log gets a 'set_word_type' action for the admin re-tag.
--
-- Idempotent: IF NOT EXISTS / CREATE OR REPLACE / DROP ... IF EXISTS, and the
-- UPDATE only touches rows that aren't already names.
-- =============================================================================

DO $$
BEGIN
  CREATE TYPE public.word_type AS ENUM ('vocabulary', 'name');
EXCEPTION WHEN duplicate_object THEN
  NULL;
END
$$;

ALTER TABLE public.words
  ADD COLUMN IF NOT EXISTS word_type public.word_type NOT NULL DEFAULT 'vocabulary';

COMMENT ON COLUMN public.words.word_type IS
  'vocabulary: a Motu word. name: a personal or place name (mostly from the Bible), kept out of Contribute and counted separately (#75).';

-- ADD VALUE can't be used in the transaction that adds it; nothing below
-- uses it as a literal (the UPDATE compares action::text).
ALTER TYPE public.moderation_action ADD VALUE IF NOT EXISTS 'set_word_type';

-- The list order within a type (search_words, word_neighbors)
CREATE INDEX IF NOT EXISTS idx_words_type_frequency_motu_word
  ON public.words (word_type, frequency DESC NULLS LAST, motu_word);

