-- --- Contribute never offers a name -----------------------------------------
-- As in 20261024110000, plus the word_type condition.
CREATE OR REPLACE FUNCTION public.get_next_word_for_user(
  user_uuid uuid DEFAULT NULL,
  exclude_ids uuid[] DEFAULT '{}'
)
RETURNS TABLE(
  id uuid,
  motu_word text,
  frequency integer,
  example_reference text,
  example_motu text,
  example_english text,
  suggested_translations text[],
  status public.word_status,
  consensus_gloss text,
  total_contributions integer
)
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  -- user_uuid is ignored on purpose: the caller is always auth.uid().
  caller uuid := auth.uid();
  skipped uuid[] := COALESCE(exclude_ids, '{}');
BEGIN
  IF caller IS NULL THEN
    RETURN;
  END IF;

  FOR attempt IN 1..2 LOOP
    RETURN QUERY
    SELECT
      w.id,
      w.motu_word,
      w.frequency,
      w.example_reference,
      w.example_motu,
      w.example_english,
      w.suggested_translations,
      w.status,
      w.consensus_gloss,
      w.total_contributions
    FROM words w
    -- Names and places aren't vocabulary to translate (#75)
    WHERE w.word_type = 'vocabulary'
    AND NOT (w.id = ANY (skipped))
    AND NOT EXISTS (
      -- Exclude words the member has already contributed to
      SELECT 1 FROM contributions c
      WHERE c.word_id = w.id AND c.user_id = caller
    )
    AND NOT EXISTS (
      -- Exclude words the member has marked as complete
      SELECT 1 FROM user_word_completion uwc
      WHERE uwc.word_id = w.id AND uwc.user_id = caller
    )
    -- Weighted random pick, probability proportional to frequency.
    -- 1 - random() is in (0, 1], so ln() never sees 0.
    ORDER BY -ln(1 - random()) / GREATEST(COALESCE(w.frequency, 0), 1)
    LIMIT 1;

    -- Found one, or there was nothing to relax.
    IF FOUND OR cardinality(skipped) = 0 THEN
      RETURN;
    END IF;

    -- Every remaining word was skipped recently: offer them again.
    skipped := '{}';
  END LOOP;
END;
$$;

ALTER FUNCTION public.get_next_word_for_user(uuid, uuid[]) OWNER TO postgres;

REVOKE ALL ON FUNCTION public.get_next_word_for_user(uuid, uuid[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_next_word_for_user(uuid, uuid[]) TO authenticated, service_role;

-- --- Browsing by type ---------------------------------------------------------
-- The old signatures are replaced, not overloaded, so a call without
-- p_word_type resolves to one function and gets every word, as before.
DROP FUNCTION IF EXISTS public.word_initials();

CREATE OR REPLACE FUNCTION public.word_initials(p_word_type text DEFAULT NULL)
RETURNS TABLE(letter text, word_count bigint)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO ''
AS $$
  SELECT upper(left(w.motu_word, 1)) AS letter, count(*) AS word_count
  FROM public.words w
  WHERE p_word_type IS NULL OR w.word_type::text = p_word_type
  GROUP BY 1;
$$;

DROP FUNCTION IF EXISTS public.search_words(text, text, text, text);

CREATE OR REPLACE FUNCTION public.search_words(
  p_motu text DEFAULT NULL,
  p_english text DEFAULT NULL,
  p_letter text DEFAULT NULL,
  p_status text DEFAULT NULL,
  p_word_type text DEFAULT NULL
)
RETURNS SETOF public.words
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path TO ''
AS $$
DECLARE
  english_pats text[];
BEGIN
  IF coalesce(p_english, '') <> '' THEN
    -- One pattern per term; input with no terms left (such as ",") is
    -- matched as typed, minus line breaks.
    SELECT array_agg('%' || public.escape_like(lower(t.term)) || '%')
      INTO english_pats
      FROM regexp_split_to_table(p_english, '[,;\r\n]') AS s(raw),
           btrim(s.raw) AS t(term)
     WHERE t.term <> '';

    english_pats := coalesce(
      english_pats,
      ARRAY['%' || public.escape_like(lower(regexp_replace(p_english, '[\r\n]', '', 'g'))) || '%']
    );
  END IF;

  -- Dynamic SQL so each call is planned with its own patterns, which lets the
  -- planner use the trigram index for selective searches.
  RETURN QUERY EXECUTE
    'SELECT w.* FROM public.words w WHERE true'
    || CASE WHEN coalesce(p_motu, '') <> ''
            THEN ' AND w.motu_word ILIKE ''%'' || public.escape_like($1) || ''%''' ELSE '' END
    || CASE WHEN english_pats IS NOT NULL
            THEN ' AND public.word_search_text(w.consensus_gloss, w.suggested_translations) LIKE ANY ($2)' ELSE '' END
    -- Same expression as word_initials(), so every letter it lists matches
    -- its words whatever the collation's case mapping (Ḡ/ḡ included).
    || CASE WHEN coalesce(p_letter, '') <> ''
            THEN ' AND upper(left(w.motu_word, 1)) = $3' ELSE '' END
    || CASE WHEN coalesce(p_status, '') <> ''
            THEN ' AND w.status::text = $4' ELSE '' END
    || CASE WHEN coalesce(p_word_type, '') <> ''
            THEN ' AND w.word_type::text = $5' ELSE '' END
    USING p_motu, english_pats, p_letter, p_status, p_word_type;
END;
$$;

-- Prev/Next stay within the current word's type, in the list's order.
CREATE OR REPLACE FUNCTION public.word_neighbors(p_word_id uuid)
RETURNS TABLE(direction text, id uuid, motu_word text)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO ''
AS $$
  -- A null frequency sorts last, like the list (NULLS LAST); frequencies are
  -- never negative, so -1 stands in for it.
  WITH cur AS (
    SELECT coalesce(w.frequency, -1) AS f, w.motu_word AS m, w.word_type AS t
    FROM public.words w
    WHERE w.id = p_word_id
  )
  (
    SELECT 'prev', w.id, w.motu_word
    FROM public.words w, cur
    WHERE w.word_type = cur.t
      AND (coalesce(w.frequency, -1) > cur.f
           OR (coalesce(w.frequency, -1) = cur.f AND w.motu_word < cur.m))
    ORDER BY coalesce(w.frequency, -1) ASC, w.motu_word DESC
    LIMIT 1
  )
  UNION ALL
  (
    SELECT 'next', w.id, w.motu_word
    FROM public.words w, cur
    WHERE w.word_type = cur.t
      AND (coalesce(w.frequency, -1) < cur.f
           OR (coalesce(w.frequency, -1) = cur.f AND w.motu_word > cur.m))
    ORDER BY coalesce(w.frequency, -1) DESC, w.motu_word ASC
    LIMIT 1
  );
$$;

REVOKE ALL ON FUNCTION public.word_initials(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.search_words(text, text, text, text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.word_neighbors(uuid) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION public.word_initials(text) TO anon, authenticated;
GRANT EXECUTE ON FUNCTION public.search_words(text, text, text, text, text) TO anon, authenticated;
GRANT EXECUTE ON FUNCTION public.word_neighbors(uuid) TO anon, authenticated;
